using System; using TMPro; using UnityEngine;
namespace ThinkingSpace.UI.DesignKit { public sealed class QuestUIOrbySpeechBubble:MonoBehaviour { [SerializeField] private TMP_Text subtitle; [SerializeField] private bool expanded; public TMP_Text Subtitle=>subtitle; public bool Expanded=>expanded; public void Configure(TMP_Text value,bool state){subtitle=value;expanded=state;} public void SetSubtitle(string value){if(subtitle!=null)subtitle.text=value??string.Empty;} public static float DisplayDuration(string value){int words=string.IsNullOrWhiteSpace(value)?0:value.Split((char[])null,StringSplitOptions.RemoveEmptyEntries).Length;return Mathf.Clamp(1.5f+words/2.5f,3f,14f);} } }
